item.command:
/bin/bash -lc "bash -lc 'echo \"Searching for .jsonl files under likely locations...\"; set -e; 
for p in /workspace /workspace/.agents /workspace/.codex /home/agent /tmp; do
  if [ -d \""'$p" ]; then
    echo "-- $p";
    rg --files -uu -g "*.jsonl" "$p" 2>/dev/null || true;
  fi
done'"'"

